parameters.jsCode:
// leo el texto que devuelve Gemini y lo parseo
const texto = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text;
if (!texto) {
  throw new Error('Gemini no devolvio texto: ' + JSON.stringify($input.first().json).slice(0, 200));
}
const r = JSON.parse(texto);
const categorias = ['facturacion', 'tecnico', 'ventas', 'otro'];
const urgencias = ['alta', 'media', 'baja'];

// si el modelo se sale del formato, caigo a valores seguros en vez de propagar basura
const categoria = categorias.includes(r.categoria) ? r.categoria : 'otro';
const urgencia = urgencias.includes(r.urgencia) ? r.urgencia : 'media';

return [{ json: { categoria, urgencia, resumen: String(r.resumen ?? '').slice(0, 200), atenderHoy: urgencia === 'alta' } }];
